function X = kalman_update_fast(Z, model)
  % KALMAN_UPDATE_FAST  Constant-velocity Kalman filter over a batch of measurements.
  %
  %   X = kalman_update_fast(Z, model)
  %
  %   Drop-in replacement for KALMAN_UPDATE (CVT estimator v2.1.0) with the
  %   same inputs and outputs:
  %
  %   Z      N-by-m matrix; row k is the measurement z_k (columns beyond m,
  %          the number of rows of H, are ignored, as in the original).
  %   model  struct with fields F (n-by-n), Q (n-by-n), H (m-by-n), R (m-by-m),
  %          x0 (n-by-1), P0 (n-by-n).
  %   X      N-by-n matrix; row k is the posterior state estimate after step k.
  %
  % Same recursion as the original, per CVT-EST-001 Rev B section 4:
  %     x = F x;            P = F P F' + Q
  %     y = z - H x;        S = H P H' + R
  %     K = P H' inv(S);    x = x + K y;   P = (I - K H) P
  %
  % Output is bit-identical to KALMAN_UPDATE for any model with m == 2.
  % Every matrix product is computed by MM, which accumulates the
  % inner-dimension terms in the same left-to-right order as the original's
  % scalar loops (s = 0; s = s + A(i,p)*B(p,j)), but a whole matrix at a time.
  % The built-in matrix multiply is deliberately not used, because BLAS adds the
  % terms in a different order and its result is not bit-identical. Loop
  % invariants (F', H', I) are hoisted, and the output is written a row at a
  % time. For m == 2 S is inverted in closed form exactly as in the original.
  % For any other measurement dimension (which the original does not support),
  % K is obtained by solving against S.

  F = model.F; Q = model.Q; H = model.H; R = model.R;
  x = model.x0(:); P = model.P0;

  N = size(Z, 1);
  n = numel(x);
  m = size(H, 1);
  X = zeros(N, n);

  Ft = F.';
  Ht = H.';
  I  = eye(n);
  Zt = Z(:, 1:m).';                      % m x N, one column per step

  for k = 1:N
    % --- predict ---
    x = mm(F, x);
    P = mm(mm(F, P), Ft) + Q;

    % --- update ---
    PHt = mm(P, Ht);                     % n x m
    S   = mm(H, PHt) + R;                % m x m
    if m == 2
      d    = S(1, 1) * S(2, 2) - S(1, 2) * S(2, 1);
      Sinv = [S(2, 2) / d, -S(1, 2) / d; -S(2, 1) / d, S(1, 1) / d];
      K    = mm(PHt, Sinv);              % n x 2
    else
      K    = PHt / S;                    % n x m
    end
    y = Zt(:, k) - mm(H, x);             % m x 1
    x = x + mm(K, y);
    P = mm(I - mm(K, H), P);

    X(k, :) = x.';
  end
end

function C = mm(A, B)
  % C = A*B with each element summed as ((0 + a1*b1) + a2*b2) + ..., the same
  % order and starting value as the original's matmul/matvec. The products are
  % element-wise, so each term is one correctly rounded multiply.
  C = zeros(size(A, 1), size(B, 2));
  for p = 1:size(A, 2)
    C = C + A(:, p) .* B(p, :);
  end
end

