  % Every product C = A*B is accumulated as
  %     C = 0;  for p = 1:inner,  C = C + A(:,p) .* B(p,:);  end
  % This is the same order and starting value as the original's scalar loops
  % (s = 0; s = s + A(i,p)*B(p,j)), but a whole matrix at a time, and each term
  % is one correctly rounded element-wise multiply. The built-in matrix
  % multiply is deliberately not used, because BLAS adds the terms in a
  % different order and its result is not bit-identical. These loops are
  % written inline rather than as a helper function, because function-call
  % overhead would otherwise dominate the run time. Loop invariants (F', H', I,
  % zero matrices) are hoisted. For m == 2, S is inverted in closed form exactly
  % as in the original. For any other measurement dimension (which the original
  % does not support), K is obtained by solving against S.

  F = model.F; Q = model.Q; H = model.H; R = model.R;
  x = model.x0(:); P = model.P0;

  N = size(Z, 1);
  n = numel(x);
  m = size(H, 1);
  X = zeros(N, n);

  Ft = F.';
  Ht = H.';
  I  = eye(n);
  Zt = Z(:, 1:m).';                      % m x N, one column per step
  zn1 = zeros(n, 1); znn = zeros(n, n);
  zm1 = zeros(m, 1); zmm = zeros(m, m); znm = zeros(n, m);

  for k = 1:N
    % --- predict ---
    % x = F x
    xp = zn1;
    for p = 1:n, xp = xp + F(:, p) .* x(p); end
    x = xp;
    % P = (F P) F' + Q
    FP = znn;
    for p = 1:n, FP = FP + F(:, p) .* P(p, :); end
    P = znn;
    for p = 1:n, P = P + FP(:, p) .* Ft(p, :); end
    P = P + Q;

    % --- update ---
    % PHt = P H'                           n x m
    PHt = znm;
    for p = 1:n, PHt = PHt + P(:, p) .* Ht(p, :); end
    % S = H PHt + R                        m x m
    S = zmm;
    for p = 1:n, S = S + H(:, p) .* PHt(p, :); end
    S = S + R;
    % K = PHt inv(S)                       n x m
    if m == 2
      d    = S(1, 1) * S(2, 2) - S(1, 2) * S(2, 1);
      Sinv = [S(2, 2) / d, -S(1, 2) / d; -S(2, 1) / d, S(1, 1) / d];
      K = znm;
      for p = 1:m, K = K + PHt(:, p) .* Sinv(p, :); end
    else
      K = PHt / S;
    end
    % y = z - H x                          m x 1
    Hx = zm1;
    for p = 1:n, Hx = Hx + H(:, p) .* x(p); end
    y = Zt(:, k) - Hx;
    % x = x + K y
    Ky = zn1;
    for p = 1:m, Ky = Ky + K(:, p) .* y(p); end
    x = x + Ky;
    % P = (I - K H) P
    KH = znn;
    for p = 1:m, KH = KH + K(:, p) .* H(p, :); end
    IKH = I - KH;
    P = znn;
    for p = 1:n, P = P + IKH(:, p) .* FP_dummy_guard(P); end %#ok<NASGU>

    X(k, :) = x.';
  end
end

