1	% BENCHMARK_KALMAN_UPDATE  Equivalence check and benchmark of kalman_update
2	% (v2.1.0) against kalman_update_fast (v2.2.0) on the sample stream.
3	%
4	% Runs in MATLAB or GNU Octave from this directory. Errors if the maximum
5	% absolute difference exceeds the 1e-9 tolerance.
6	
7	tol   = 1e-9;
8	nreps = 5;                                   % timed repetitions per routine
9	
10	here  = fileparts(mfilename('fullpath'));
11	if isempty(here), here = pwd; end
12	Z     = dlmread(fullfile(here, 'test_vectors.csv'), ',', 1, 0);   % skip header
13	model = jsondecode(fileread(fullfile(here, 'model.json')));
14	
15	N = size(Z, 1);
16	fprintf('Vectors: %d   (state n = %d, measurement m = %d)\n', ...
17	        N, numel(model.x0), size(model.H, 1));
18	
19	% --- equivalence on the sample ---------------------------------------------
20	X_ref  = kalman_update(Z, model);
21	X_fast = kalman_update_fast(Z, model);
22	assert(isequal(size(X_ref), size(X_fast)), 'Output sizes differ.');
23	max_err = max(abs(X_ref(:) - X_fast(:)));
24	fprintf('Max abs error (sample model):   %.3e\n', max_err);
25	
26	% --- equivalence on other models the original supports (any n, m = 2) ------
27	rand('seed', 1); randn('seed', 1);           % reproducible in MATLAB and Octave
28	max_err_other = 0;
29	for n = [2 3 4 6]
30	  A = randn(n);  B = randn(2);  C = randn(n);
31	  m2.F  = eye(n) + 0.1 * randn(n);
32	  m2.Q  = 0.01 * (A * A') + 1e-3 * eye(n);
33	  m2.H  = randn(2, n);
34	  m2.R  = 0.1 * (B * B') + 0.05 * eye(2);
35	  m2.x0 = randn(n, 1);
36	  m2.P0 = C * C' + eye(n);
37	  Zr = randn(300, 2);
38	  e = max(max(abs(kalman_update(Zr, m2) - kalman_update_fast(Zr, m2))));
39	  max_err_other = max(max_err_other, e);
40	end
41	fprintf('Max abs error (random models):  %.3e\n', max_err_other);
42	
43	% --- equivalence on long, production-length streams ------------------------
44	% The tolerance is absolute and positions grow along the stream, so check
45	% streams simulated from the CV model that reach much larger |x| than the
46	% sample. Slow: the original routine needs several minutes per stream.
47	% Set run_long = false to skip.
48	run_long = true;
49	N_long   = 100000;
50	max_err_long = 0;
51	if run_long
52	  % Stream 1: the production model.json (dt = 1).
53	  % Stream 2: CV model with dt = 0.1, discrete white-noise-acceleration Q,
54	  %           correlated (non-diagonal) R, nonzero x0.
55	  dt = 0.1; q = 0.5; I2 = eye(2);
56	  cv.F  = [I2, dt * I2; zeros(2), I2];
57	  cv.Q  = q * [dt^3 / 3 * I2, dt^2 / 2 * I2; dt^2 / 2 * I2, dt * I2];
